@NotNull
	@Override
	public ItemStack finishUsingItem(@NotNull ItemStack stack, Level world, LivingEntity living) {
		String tag = TAG_TARGET_PREFIX + world.dimension().location();
		Tag nbt = ItemNBTHelper.get(stack, tag);
		if (nbt == null) {
			return stack;
		}
		Optional<BlockPos> maybeLoc = BlockPos.CODEC.parse(NbtOps.INSTANCE, nbt).result();
		if (!maybeLoc.isPresent()) {
			ItemNBTHelper.removeEntry(stack, tag);
			return stack;
		}
		BlockPos loc = maybeLoc.get();
		int x = loc.getX();
		int y = loc.getY();
		int z = loc.getZ();

		int cost = (int) (MathHelper.pointDistanceSpace(x + 0.5, y + 0.5, z + 0.5, living.getX(), living.getY(), living.getZ()) * 10);

		if (!(living instanceof Player player) || ManaItemHandler.instance().requestManaExact(stack, player, cost, true)) {
			moveParticlesAndSound(living);
			Vec3 sourcePos = living.position();
			living.teleportTo(x + 0.5, y + 1.5, z + 0.5);
			world.gameEvent(living, GameEvent.TELEPORT, sourcePos);
			moveParticlesAndSound(living);
		}

		return stack;
	}

@Override
	public int getUseDuration(ItemStack stack) {
		return 40;
	}

private static void moveParticlesAndSound(Entity entity) {
		XplatAbstractions.INSTANCE.sendToTracking(entity, new BotaniaEffectPacket(EffectType.FLUGEL_EFFECT, entity.getX(), entity.getY(), entity.getZ(), entity.getId()));
		entity.level().playSound(null, entity.getX(), entity.getY(), entity.getZ(), BotaniaSounds.flugelEyeTeleport, SoundSource.PLAYERS, 1F, 1F);
	}

public void handle(MinecraftServer server, ServerPlayer player) {
		server.execute(() -> {
			player.level().playSound(null, player.getX(), player.getY(), player.getZ(), BotaniaSounds.dash, SoundSource.PLAYERS, 1F, 1F);

			ItemStack ringStack = EquipmentHandler.findOrEmpty(BotaniaItems.dodgeRing, player);
			if (ringStack.isEmpty()) {
				player.connection.disconnect(Component.translatable("botaniamisc.invalidDodge"));
				return;
			}

			player.causeFoodExhaustion(0.3F);
			ItemNBTHelper.setInt(ringStack, RingOfDexterousMotionItem.TAG_DODGE_COOLDOWN, RingOfDexterousMotionItem.MAX_CD);
		});
	}

public static void onKeyDown() {
			Minecraft mc = Minecraft.getInstance();
			if (mc.player == null) {
				return;
			}

			ItemStack ringStack = EquipmentHandler.findOrEmpty(BotaniaItems.dodgeRing, mc.player);
			if (ringStack.isEmpty() || ItemNBTHelper.getInt(ringStack, TAG_DODGE_COOLDOWN, 0) > 0) {
				return;
			}

			int threshold = 5;
			if (mc.options.keyLeft.isDown() && !oldLeftDown) {
				int oldLeft = leftDown;
				leftDown = ClientTickHandler.ticksInGame;

				if (leftDown - oldLeft < threshold) {
					dodge(mc.player, Direction.WEST);
				}
			} else if (mc.options.keyRight.isDown() && !oldRightDown) {
				int oldRight = rightDown;
				rightDown = ClientTickHandler.ticksInGame;

				if (rightDown - oldRight < threshold) {
					dodge(mc.player, Direction.EAST);
				}
			} else if (mc.options.keyUp.isDown() && !oldForwardDown) {
				int oldForward = forwardDown;
				forwardDown = ClientTickHandler.ticksInGame;

				if (forwardDown - oldForward < threshold) {
					dodge(mc.player, Direction.NORTH);
				}
			} else if (mc.options.keyDown.isDown() && !oldBackDown) {
				int oldBack = backDown;
				backDown = ClientTickHandler.ticksInGame;

				if (backDown - oldBack < threshold) {
					dodge(mc.player, Direction.SOUTH);
				}
			}

			oldLeftDown = mc.options.keyLeft.isDown();
			oldRightDown = mc.options.keyRight.isDown();
			oldForwardDown = mc.options.keyUp.isDown();
			oldBackDown = mc.options.keyDown.isDown();
		}

private static void dodge(Player player, Direction dir) {
		if (player.getAbilities().flying || !player.onGround() || dir == Direction.UP || dir == Direction.DOWN) {
			return;
		}

		float yaw = player.getYRot();
		float x = Mth.sin(-yaw * 0.017453292F - (float) Math.PI);
		float z = Mth.cos(-yaw * 0.017453292F - (float) Math.PI);
		if (dir == Direction.NORTH || dir == Direction.SOUTH) {
			x = Mth.cos(-yaw * 0.017453292F);
			z = Mth.sin(yaw * 0.017453292F);
		}
		Vec3 lookVec = new Vec3(x, 0, z);
		Vec3 sideVec = lookVec.cross(new Vec3(0, dir == Direction.WEST || dir == Direction.NORTH ? 1 : (dir == Direction.EAST || dir == Direction.SOUTH ? -1 : 0), 0)).scale(1.25);

		player.setDeltaMovement(sideVec);

		ClientXplatAbstractions.INSTANCE.sendToServer(DodgePacket.INSTANCE);
	}

@Override
	public void onWornTick(ItemStack stack, LivingEntity living) {
		int cd = ItemNBTHelper.getInt(stack, TAG_DODGE_COOLDOWN, 0);
		if (cd > 0) {
			ItemNBTHelper.setInt(stack, TAG_DODGE_COOLDOWN, cd - 1);
		}
	}

public static void handleRollPublish(Packets.RollPublish packet, MinecraftServer server, ServerPlayer player) {
        ServerLevel world = Iterables.tryFind(server.getAllLevels(), (element) -> element == player.level())
                .orNull();
        final var velocity = packet.velocity();
        final var forwardPacket = new Packets.RollAnimation(player.getId(), packet.visuals(), packet.velocity());
        Platform.tracking(player).forEach(serverPlayer -> {
            try {
                if (serverPlayer.getId() != player.getId() && Platform.networkS2C_CanSend(serverPlayer, Packets.RollAnimation.PACKET_ID)) {
                    Platform.networkS2C_Send(serverPlayer, forwardPacket);
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        });

        world.getServer().executeIfPossible(() -> {
            ((RollInvulnerable)player).setRollInvulnerableTicks(CombatRollMod.config.invulnerable_ticks_upon_roll);
            player.causeFoodExhaustion(CombatRollMod.config.exhaust_on_roll);
            player.awardStat(CombatRollStats.ROLL.stat);
            // 1.5D to approximate difference between velocity and actual travel
            player.awardStat(CombatRollStats.ROLL_CM.stat, (int)(velocity.length() * 100 * 1.5D));
            var proxy = (Event.Proxy<ServerSideRollEvents.PlayerStartRolling>)ServerSideRollEvents.PLAYER_START_ROLLING;
            proxy.handlers.forEach(hander -> { hander.onPlayerStartedRolling(player, velocity);});
        });
    }

private void tryRolling() {
        var client = (Minecraft) ((Object)this);
        if (player == null || client.isPaused() || client.gui.screen() != null) {
            return;
        }
        var rollingPlayer = ((RollingEntity)player);
        var rollManager = rollingPlayer.getRollManager();
        if (Keybindings.roll.isDown()) {
            if(!rollManager.isRollAvailable(player)) {
                return;
            }
            if(!CombatRollMod.config.allow_rolling_while_airborn && !player.onGround()) {
                return;
            }
            if(player.getFoodData().getFoodLevel() <= CombatRollMod.config.food_level_required) {
                return;
            }
            if(player.isSwimming() || player.isVisuallyCrawling()) {
                return;
            }
            if(player.getVehicle() != null) {
                return;
            }
            if(player.isUsingItem() || player.isBlocking()) {
                return;
            }
            if (!CombatRollMod.config.allow_rolling_while_weapon_cooldown && player.getAttackStrengthScale(0) < 0.95) {
                return;
            }
            if (BetterCombatHelper.isDoingUpswing()) {
                BetterCombatHelper.cancelUpswing();
            } else {
                if (client.options.keyAttack.isDown()) {
                    return;
                }
            }
            if (rightClickDelay > 0) {
                return;
            }

            var forward = player.zza;
            var sideways = player.xxa;
            Vec3 direction;
            if (forward == 0 && sideways == 0) {
                direction = new Vec3(0, 0, 1);
            } else  {
                direction = new Vec3(sideways, 0, forward).normalize();
            }
            direction = direction.yRot((float) Math.toRadians((-1.0) * player.getYRot()));
            var distance = 0.475 *
                    (player.getAttributeValue(CombatRoll.Attributes.DISTANCE.entry)
                    + CombatRollMod.config.additional_roll_distance);
            direction = direction.scale(distance);

            if (player.isInWater()) {
                var liquidHeight = player.getFluidHeight(FluidTags.WATER);
                liquidHeight = Math.min(liquidHeight, 1F);
                var multiplier = Math.max(1 - (liquidHeight*3), 0.3);
                // System.out.println("Water! " + multiplier + " liquidHeight: " + liquidHeight);
                direction = direction.scale(multiplier);
            }

            if (player.isInLava()) {
                var liquidHeight = player.getFluidHeight(FluidTags.LAVA);
                liquidHeight = Math.min(liquidHeight, 1F);
                // System.out.println("Lava! " + liquidHeight * 0.3);
                direction = direction.scale(0.3);
            }

            var block = player.level().getBlockState(player.blockPosition().below()).getBlock();
            var slipperiness = block.getFriction();
            var defaultSlipperiness = Blocks.GRASS_BLOCK.getFriction();
            if (slipperiness > defaultSlipperiness) {
                var multiplier = defaultSlipperiness / slipperiness;
                direction = direction.scale(multiplier * multiplier);
            }

            player.push(direction.x, direction.y, direction.z);
            rollManager.onRoll(player);

            var rollVisuals = new RollEffect.Visuals(CombatRollMod.ID + ":roll", PUFF);
            Platform.networkC2S_Send(new Packets.RollPublish(player.getId(), rollVisuals, direction));
            RollEffect.playVisuals(rollVisuals, player, direction);
        }
    }

public void onRoll(LocalPlayer player) {
        availableRolls -= 1;
        timeSinceLastRoll = 0;
        updateCooldownLength(player);
    }

public void tick(LocalPlayer player) {
        maxRolls = (int) player.getAttributeValue(CombatRoll.Attributes.COUNT.entry);
        timeSinceLastRoll += 1;
        if (availableRolls < maxRolls) {
            currentCooldownProgress += increment(player);
            if (currentCooldownProgress >= currentCooldownLength) {
                rechargeRoll(player);
            }
        }
        if (availableRolls == maxRolls) {
            currentCooldownProgress = 0;
        }
        if (availableRolls > maxRolls) {
            availableRolls = maxRolls;
        }
    }

public boolean isRollAvailable(Player player) {
        return isEnabled
                && !isRolling()
                && availableRolls > 0
                && !((PlayerEntityAccessor)player).invokeIsImmobile_combat_roll()
                && player.canSimulateMovement()
                && player.getAttributeValue(Attributes.MOVEMENT_SPEED) > 0;
    }

public boolean isRolling() {
        return timeSinceLastRoll <= rollDuration();
    }

private void rechargeRoll(LocalPlayer player) {
        availableRolls += 1;
        currentCooldownProgress = Math.max(currentCooldownProgress - currentCooldownLength, 0);
        updateCooldownLength(player);
        if (CombatRollClient.config.playCooldownSound) {
            var cooldownReady = BuiltInRegistries.SOUND_EVENT.getValue(Identifier.parse("combat_roll:roll_cooldown_ready"));
            if (cooldownReady != null) {
                player.level().playLocalSound(player.getX(), player.getY(), player.getZ(), cooldownReady, SoundSource.PLAYERS, 1, 1, false);
            }
        }
    }

private void updateCooldownLength(LocalPlayer player) {
        var duration = CombatRollMod.config.roll_cooldown;
        currentCooldownLength = Math.round(duration * 20F);
    }

private float increment(Player player) {
        return (float) (player.getAttributeValue(CombatRoll.Attributes.RECHARGE.entry) / 20F);
    }

@Inject(method = "tick", at = @At("TAIL"))
    private void tick_TAIL(CallbackInfo ci) {
        var player = (LocalPlayer) ((Object)this);
        if (player != null) {
            rollManager.tick(player);
        }
    }

@Override
    public void setRollInvulnerableTicks(int ticks) {
        invulnerableTicks = ticks;
    }

@Inject(method = "tick", at = @At("TAIL"))
    private void tick_TAIL_combat_roll(CallbackInfo ci) {
        if (invulnerableTicks > 0) {
            invulnerableTicks -= 1;
        }
    }

@Inject(method = "hurtServer", at = @At("HEAD"), cancellable = true)
    private void damage_HEAD_combat_roll(ServerLevel world, DamageSource source, float amount, CallbackInfoReturnable<Boolean> cir) {
        if (invulnerableTicks > 0) {
            cir.setReturnValue(false);
            cir.cancel();
        }
    }

public static void handleRollAnimation(Packets.RollAnimation packet) {
        var client = Minecraft.getInstance(); // NeoForge network handler context doesn't provide a client instance
        client.execute(() -> {
            var entity = client.level.getEntity(packet.playerId());
            if (entity instanceof Player player) {
                RollEffect.playVisuals(packet.visuals(), player, packet.velocity());
            }
        });
    }

public static void init() {
        // Config stage
        PayloadTypeRegistry.clientboundConfiguration().register(Packets.ConfigSync.PACKET_ID, Packets.ConfigSync.CODEC);
        PayloadTypeRegistry.serverboundConfiguration().register(Packets.Ack.PACKET_ID, Packets.Ack.CODEC);

        ServerConfigurationConnectionEvents.CONFIGURE.register((handler, server) -> {
            // This if block is required! Otherwise the client gets stuck in connection screen
            // if the client cannot handle the packet.
            if (ServerConfigurationNetworking.canSend(handler, Packets.ConfigSync.ID)) {
                handler.addTask(new ConfigurationTask(Packets.ConfigSync.serialize(CombatRollMod.config)));
            }
        });

        ServerConfigurationNetworking.registerGlobalReceiver(Packets.Ack.PACKET_ID, (packet, context) -> {
            if (packet.code().equals(ConfigurationTask.name)) {
                context.packetListener().completeTask(ConfigurationTask.KEY);
            }
        });

        // Play stage
        PayloadTypeRegistry.serverboundPlay().register(Packets.RollPublish.PACKET_ID, Packets.RollPublish.CODEC);
        PayloadTypeRegistry.clientboundPlay().register(Packets.RollAnimation.PACKET_ID, Packets.RollAnimation.CODEC);

        ServerPlayNetworking.registerGlobalReceiver(Packets.RollPublish.PACKET_ID, (packet, context) -> {
            ServerNetwork.handleRollPublish(packet, context.server(), context.player());
        });
    }

@SubscribeEvent
    public static void register(final RegisterPayloadHandlersEvent event) {
        final PayloadRegistrar registrar = event.registrar("1");

        // Server

        registrar.configurationToServer(Packets.Ack.PACKET_ID, Packets.Ack.CODEC, (payload, context) -> {
            if (payload.code().equals(ConfigurationTask.ID.toString())) {
                context.finishCurrentTask(ConfigurationTask.KEY);
            }
        });

        registrar.playToServer(Packets.RollPublish.PACKET_ID, Packets.RollPublish.CODEC, (packet, context) -> {
            var player = (ServerPlayer)context.player();
            var server = player.level().getServer();
            ServerNetwork.handleRollPublish(packet, server, player);
        });

        // Client

        registrar.configurationToClient(Packets.ConfigSync.PACKET_ID, Packets.ConfigSync.CODEC, (packet, context) -> {
            ClientNetwork.handleConfigSync(packet);
            context.reply(new Packets.Ack(ConfigurationTask.ID.toString()));
        });

        registrar.playToClient(Packets.RollAnimation.PACKET_ID, Packets.RollAnimation.CODEC, (packet, context) -> {
            ClientNetwork.handleRollAnimation(packet);
        });
    }
